import{_ as o,C as i,o as t,c as r,a2 as a,b as l,w as n,a as d,E as c,a3 as g}from"./chunks/framework.Brv5O9VI.js";const A=JSON.parse('{"title":"14.4 Load Balancing & Scaling Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.4-load-balancing-and-scaling.md","filePath":"system-design/14.4-load-balancing-and-scaling.md"}'),h={name:"system-design/14.4-load-balancing-and-scaling.md"};function u(p,e,m,f,b,y){const s=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="_14-4-load-balancing-scaling-strategy" tabindex="-1">14.4 Load Balancing &amp; Scaling Strategy <a class="header-anchor" href="#_14-4-load-balancing-scaling-strategy" aria-label="Permalink to &quot;14.4 Load Balancing &amp; Scaling Strategy&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Load balancing distributes incoming client network requests evenly across multiple backend server instances to prevent individual server crashes, eliminate single points of failure (SPOFs), and achieve horizontal scale.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><p>The backend application in [<code>app.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py) is architected to be <strong>100% stateless</strong>:</p><ul><li><strong>Stateless Handlers</strong>: No user sessions, in-memory counters, or temporary transaction states are stored across requests.</li><li><strong>Shared Read-Only Memory</strong>: The vector index and corpus are static read-only files loaded at boot.</li><li><strong>Horizontal Scale Ready</strong>: Any number of identical Docker containers can be spun up side-by-side behind a round-robin load balancer without requiring sticky sessions or distributed session stores.</li></ul>',7)),(t(),l(g,null,{default:n(()=>[c(s,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Client1%5B%22Client%20Browser%22%5D%20--%3E%20LB%5B%22Layer%207%20Reverse%20Proxy%20%2F%20Load%20Balancer%20(Nginx%20%2F%20ALB)%22%5D%0A%20%20%20%20Client2%5B%22Client%20Browser%22%5D%20--%3E%20LB%0A%20%20%20%20%0A%20%20%20%20subgraph%20Cluster%5B%22Stateless%20Autoscaling%20Node%20Pool%22%5D%0A%20%20%20%20%20%20%20%20Node1%5B%22Docker%20Pod%201%20(FastAPI%20%2B%20FAISS%20Index)%22%5D%0A%20%20%20%20%20%20%20%20Node2%5B%22Docker%20Pod%202%20(FastAPI%20%2B%20FAISS%20Index)%22%5D%0A%20%20%20%20%20%20%20%20Node3%5B%22Docker%20Pod%203%20(FastAPI%20%2B%20FAISS%20Index)%22%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20LB%20--%3E%7CLeast%20Connections%7C%20Node1%0A%20%20%20%20LB%20--%3E%7CLeast%20Connections%7C%20Node2%0A%20%20%20%20LB%20--%3E%7CLeast%20Connections%7C%20Node3%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-of-load-balancing-algorithms" tabindex="-1">3. Comparison of Load Balancing Algorithms <a class="header-anchor" href="#_3-comparison-of-load-balancing-algorithms" aria-label="Permalink to &quot;3. Comparison of Load Balancing Algorithms&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Algorithm</th><th style="text-align:left;">Mechanism</th><th style="text-align:left;">Best Use Case</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Least Connections</strong></td><td style="text-align:left;">Routes to node with fewest active requests</td><td style="text-align:left;">Variable execution times</td><td style="text-align:left;"><strong>Optimal (Handles variance between small talk &amp; ONNX embedding)</strong></td></tr><tr><td style="text-align:left;"><strong>Round Robin</strong></td><td style="text-align:left;">Sequential cyclic distribution</td><td style="text-align:left;">Uniform short requests</td><td style="text-align:left;">Acceptable baseline</td></tr><tr><td style="text-align:left;"><strong>IP Hash</strong></td><td style="text-align:left;">Hashes client IP to fixed node</td><td style="text-align:left;">Sticky session requirements</td><td style="text-align:left;">Not needed (Stateless)</td></tr><tr><td style="text-align:left;"><strong>Weighted Round Robin</strong></td><td style="text-align:left;">Allocates higher traffic to more powerful servers</td><td style="text-align:left;">Heterogeneous hardware</td><td style="text-align:left;">Useful in mixed CPU clusters</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Duplicated Memory</strong>: Because FAISS runs in-memory, running 10 horizontal container instances replicates the 65 MB index 10 times (totaling 650 MB RAM). Given low hardware costs, this trade-off is vastly preferable to managing a separate centralized vector database cluster.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: A single instance scales vertically up to 4 CPU workers cleanly.</li><li><strong>At 100x Load</strong>: Single instance saturates; requires spinning up 8-12 container replicas behind an AWS Application Load Balancer or Nginx.</li><li><strong>At 1000x Load</strong>: If updating the corpus, synchronizing new FAISS index files across 100 running container instances requires rolling blue-green deployments or mounting index files from a shared distributed read-only network volume (EFS).</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Deploy on <strong>Kubernetes (EKS / GKE)</strong> with a <strong>Horizontal Pod Autoscaler (HPA)</strong> configured with metrics:</p><ul><li>Metric: Average CPU utilization $&gt;70%$.</li><li>Health Probe: HTTP <code>GET /</code> liveness and readiness probe checked every 5 seconds.</li><li>Zero-Downtime: Rolling updates with <code>maxSurge: 25%</code> and <code>maxUnavailable: 0</code>.</li></ul><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Our application is architected to be completely stateless: the vector index and corpus are immutable read-only structures in resident RAM. Because no session state exists on the server, we can scale horizontally to dozens of container instances behind an AWS Application Load Balancer using a Least Connections algorithm with zero sticky session complexity.&quot;</p></blockquote>',16))])}const S=o(h,[["render",u]]);export{A as __pageData,S as default};
